/** Genuine glue/settings input, native previews/CT and saved moving latch/cargo. */
final class ChassisRenderingTest {
    private static final BlockPos P=new BlockPos(6103,4,5),Q=P.east(),SECONDARY=P.west(),S=P.east(8),R=P.east(12),C=new BlockPos(6127,10,5);
    private static final BlockPos STICKER=new BlockPos(2,0,0);
    private static final class Sounds implements SoundEventListener {
        private final Map<Identifier,Integer> counts=new HashMap<>();
        @Override public void onPlaySound(SoundInstance sound,WeighedSoundEvents event,float range){counts.merge(sound.getIdentifier(),1,Integer::sum);}
        int slime(){return counts.getOrDefault(Create.asResource("slime_added"),0);}
    }
    static void run(ClientGameTestContext context,TestSingleplayerContext world){var sounds=new Sounds();context.runOnClient(client->client.getSoundManager().addListener(sounds));try{scene(context,world,sounds);}finally{context.runOnClient(client->client.getSoundManager().removeListener(sounds));}}
    private static void scene(ClientGameTestContext context,TestSingleplayerContext world,Sounds sounds){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 6103.5 6 8.5");context.waitFor(client->Math.abs(client.player.getX()-6103.5)<.1&&client.level.isLoaded(R),400);NativeScreenshotReadiness.beforeFloor(context, world, new BlockPos(6098, 3, -2), new BlockPos(6140, 3, 17), P, R, new BlockPos(C.east(3).getX(), P.getY(), C.getZ()));
        server.runCommand("fill 6098 3 -2 6140 3 17 minecraft:smooth_quartz");
        NativeScreenshotReadiness.afterFloor(context, world, new BlockPos(6098, 3, -2), new BlockPos(6140, 3, 17));server.runCommand("setblock 6103 5 8 minecraft:smooth_quartz");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(P,AllBlocks.LINEAR_CHASSIS.defaultBlockState());level.setBlockAndUpdate(Q,AllBlocks.LINEAR_CHASSIS.defaultBlockState());level.setBlockAndUpdate(SECONDARY,AllBlocks.SECONDARY_LINEAR_CHASSIS.defaultBlockState());((ChassisBlockEntity)level.getBlockEntity(P)).setRange(1);((ChassisBlockEntity)level.getBlockEntity(Q)).setRange(1);((ChassisBlockEntity)level.getBlockEntity(SECONDARY)).setRange(4);});
        server.runCommand("gamemode survival @p");server.runCommand("item replace entity @p weapon.mainhand with create:super_glue");context.waitFor(client->client.player.onGround()&&client.player.getMainHandItem().is(AllItems.SUPER_GLUE),200);look(context,Vec3.atCenterOf(P).add(0,.5,0));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P)&&hit.getDirection()==Direction.UP,200);use(context);
        waitServer(context,world,level->level.getBlockState(P).getValue(LinearChassisBlock.STICKY_TOP)&&level.getServer().getPlayerList().getPlayers().getFirst().getMainHandItem().getDamageValue()==0,200,"Actual Super Glue input did not reach chassis face or consumed durability");context.runOnClient(client->{if(SuperGlueSelectionHandler.first()!=null)throw new AssertionError("Glueable chassis face incorrectly started area selection");});
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(Q,level.getBlockState(Q).setValue(LinearChassisBlock.STICKY_TOP,true));for(int y=1;y<=4;y++){level.setBlockAndUpdate(P.above(y),Blocks.STONE.defaultBlockState());level.setBlockAndUpdate(Q.above(y),Blocks.STONE.defaultBlockState());}level.setBlockAndUpdate(R,AllBlocks.RADIAL_CHASSIS.defaultBlockState().setValue(RadialChassisBlock.STICKY_WEST,true));for(var pos:List.of(R.west(),R.west().north(),R.north()))level.setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());((ChassisBlockEntity)level.getBlockEntity(R)).setRange(2);});
        server.runCommand("setblock 6103 5 8 minecraft:air");server.runCommand("tp @p 6103.5 4 8.5");server.runCommand("item replace entity @p weapon.mainhand with create:wrench");context.waitFor(client->client.player.onGround()&&client.player.getMainHandItem().is(AllItems.WRENCH)&&Math.abs(client.player.getY()-4)<.1,200);look(context,Vec3.atCenterOf(P));
        try{context.waitFor(client->ChassisRangeDisplay.latest()!=null&&ChassisRangeDisplay.latest().complete()&&ChassisRangeDisplay.latest().selected().equals(Set.of(P.above()))&&ChassisRangeDisplay.latest().faces()==6&&ChassisRangeDisplay.latest().lines()==12,200);}
        catch(AssertionError failure){throw new AssertionError(context.computeOnClient(client->"Native single chassis preview: eye="+client.player.getEyePosition()+", hit="+client.hitResult+", frame="+ChassisRangeDisplay.latest()),failure);}
        screenshot(context,"create-vulkan-chassis-real-glue-single-checker-preview");
        open(context,P);choose(context,2);waitServer(context,world,level->((ChassisBlockEntity)level.getBlockEntity(P)).getRange()==2&&((ChassisBlockEntity)level.getBlockEntity(Q)).getRange()==1,200,"Real single range commit affected wrong server members");
        context.getInput().holdKey(InputConstants.KEY_LCONTROL);
        try{open(context,P);var point=coordinate(context,3);context.getInput().setCursorPos(point.x,point.y);context.waitFor(client->ChassisRangeDisplay.latest()!=null&&ChassisRangeDisplay.latest().bulk()&&ChassisRangeDisplay.latest().selected().contains(Q.above(3)),200);screenshot(context,"create-vulkan-chassis-ctrl-connected-group-range-board");context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null,200);}finally{context.getInput().releaseKey(InputConstants.KEY_LCONTROL);}
        waitServer(context,world,level->((ChassisBlockEntity)level.getBlockEntity(P)).getRange()==3&&((ChassisBlockEntity)level.getBlockEntity(Q)).getRange()==3&&((ChassisBlockEntity)level.getBlockEntity(SECONDARY)).getRange()==4,200,"Ctrl edit did not resolve exact real group");
        var ctKey=new AtomicReference<Object>();var ctTile=new AtomicInteger();context.runOnClient(client->{var model=client.getModelManager().getBlockStateModelSet().get(client.level.getBlockState(P));if(!(model instanceof ChassisCTModel))throw new AssertionError("Linear chassis did not install native CT wrapper");ctKey.set(model.createGeometryKey(client.level,P,client.level.getBlockState(P),net.minecraft.util.RandomSource.create(42)));ctTile.set(ChassisCTModel.textureIndex(client.level,P,client.level.getBlockState(P),Direction.SOUTH));for(var block:List.of(AllBlocks.LINEAR_CHASSIS,AllBlocks.SECONDARY_LINEAR_CHASSIS,AllBlocks.RADIAL_CHASSIS,AllBlocks.STICKER))for(var state:block.getStateDefinition().getPossibleStates()){var baked=client.getModelManager().getBlockStateModelSet().get(state);if(baked==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Missing original chassis/sticker block model "+state);var mesh=net.fabricmc.fabric.api.client.renderer.v1.Renderer.get().mutableMesh();baked.emitQuads(mesh.emitter(),client.level,P,state,net.minecraft.util.RandomSource.create(42),side->false);if(mesh.immutableCopy().size()==0)throw new AssertionError("Empty chassis/sticker native model "+state);}});look(context,Vec3.atCenterOf(Q));screenshot(context,"create-vulkan-linear-primary-secondary-native-connected-textures");
        server.runCommand("setblock 6104 4 5 minecraft:air");context.waitFor(client->client.level.getBlockState(Q).isAir(),200);context.runOnClient(client->{var state=client.level.getBlockState(P);var model=client.getModelManager().getBlockStateModelSet().get(state);var next=model.createGeometryKey(client.level,P,state,net.minecraft.util.RandomSource.create(42));if(ChassisCTModel.textureIndex(client.level,P,state,Direction.SOUTH)==ctTile.get()||ctKey.get()!=null&&next!=null&&ctKey.get().equals(next))throw new AssertionError("Actual neighbor removal did not update CT context/cache identity");});
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 6115.5 4 8.5");context.waitFor(client->Math.abs(client.player.getX()-6115.5)<.1&&Math.abs(client.player.getY()-4)<.1,200);look(context,Vec3.atCenterOf(R));context.waitFor(client->ChassisRangeDisplay.latest()!=null&&ChassisRangeDisplay.latest().selected().contains(R.west().north()),200);screenshot(context,"create-vulkan-radial-native-connected-plane-preview");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(S,AllBlocks.STICKER.defaultBlockState().setValue(StickerBlock.FACING,Direction.UP));level.setBlockAndUpdate(S.above(),Blocks.GLASS.defaultBlockState());});context.waitFor(client->client.level.getBlockEntity(S) instanceof StickerBlockEntity,200);int before=context.computeOnClient(client->sounds.slime());
        server.runCommand("setblock 6111 4 4 minecraft:redstone_block");context.waitFor(client->client.level.getBlockEntity(S) instanceof StickerBlockEntity sticker&&sticker.isBlockStateExtended()&&sticker.getPiston(0)>=.999f&&sounds.slime()==before+1,200);verifySticker(context,S,.25f);look(context,Vec3.atCenterOf(S));screenshot(context,"create-vulkan-sticker-native-pulse-head-attached-sound-and-glue-particles");server.runCommand("setblock 6111 4 4 minecraft:air");context.waitTicks(5);context.runOnClient(client->{if(!client.level.getBlockState(S).getValue(StickerBlock.EXTENDED))throw new AssertionError("Falling power retracted source latch");});server.runCommand("setblock 6111 4 4 minecraft:redstone_block");context.waitFor(client->client.level.getBlockEntity(S) instanceof StickerBlockEntity sticker&&!sticker.isBlockStateExtended()&&sticker.getPiston(0)==0&&sounds.slime()==before+2,200);verifySticker(context,S,0);server.runCommand("setblock 6111 4 4 minecraft:air");
        server.runCommand("tp @p 6129.5 14 12.5");context.waitFor(client->Math.abs(client.player.getX()-6129.5)<.1&&Math.abs(client.player.getY()-14)<.1&&client.level.isLoaded(C.east(3)),300);var id=new AtomicReference<UUID>();
        NativeContraptionFixtures.awaitCaptureReady(context,world,300,C,C.east(),C.east(2),C.east(3));
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(C,AllBlocks.LINEAR_CHASSIS.defaultBlockState().setValue(AbstractChassisBlock.AXIS,Direction.Axis.X).setValue(LinearChassisBlock.STICKY_TOP,true));((ChassisBlockEntity)level.getBlockEntity(C)).setRange(3);level.setBlockAndUpdate(C.east(),Blocks.BARREL.defaultBlockState());var stock=new ItemStack(Items.DIAMOND,7);stock.set(DataComponents.CUSTOM_NAME,Component.literal("Saved chassis carrier"));((BarrelBlockEntity)level.getBlockEntity(C.east())).setItem(0,stock);level.setBlockAndUpdate(C.east(2),AllBlocks.STICKER.defaultBlockState().setValue(StickerBlock.FACING,Direction.EAST).setValue(StickerBlock.EXTENDED,true));level.setBlockAndUpdate(C.east(3),Blocks.STONE.defaultBlockState());var structure=new BearingContraption(false,Direction.UP);try{if(!structure.assemble(level,C.below())||structure.getBlocks().size()!=4||!structure.tryRemoveBlocksFromWorld(level,BlockPos.ZERO))throw new AssertionError("Real chassis/sticker selection and atomic capture failed");}catch(AssemblyException failure){throw new AssertionError(failure);}var owner=new ControlledContraptionEntity(AllEntityTypes.CONTROLLED_CONTRAPTION,level);owner.setContraption(structure);owner.setPos(Vec3.atLowerCornerOf(C));owner.setAngle(30);level.addFreshEntity(owner);id.set(owner.getUUID());});
        context.waitFor(client->find(client,id.get()) instanceof ControlledContraptionEntity owner&&owner.getContraption()!=null,300);look(context,Vec3.atCenterOf(C.east()));verifyMoving(context,id.get());screenshot(context,"create-vulkan-moving-chassis-sticker-native-head-and-range-owned-cargo");
        var old=context.computeOnClient(client->client.getModelManager().getModel(StickerRenderer.HEAD));var reload=context.computeOnClient(Minecraft::reloadResourcePacks);context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,500);reload.join();context.waitTicks(3);context.runOnClient(client->{if(client.getModelManager().getModel(StickerRenderer.HEAD)==old)throw new AssertionError("Sticker retained a stale partial model after reload");});verifyMoving(context,id.get());
        server.runCommand("tp @p 7200 15 7200");waitServer(context,world,level->level.getEntity(id.get())==null&&level.getChunkSource().getChunkNow(C.getX()>>4,0)==null,800,"Chassis owner/source chunks did not really unload");server.runCommand("tp @p 6129.5 14 12.5");waitServer(context,world,level->level.getEntity(id.get()) instanceof ControlledContraptionEntity,500,"Original saved chassis owner did not return");context.waitFor(client->find(client,id.get()) instanceof ControlledContraptionEntity owner&&owner.getContraption()!=null,300);verifyMoving(context,id.get());screenshot(context,"create-vulkan-chassis-sticker-real-unload-return-resource-reload");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var owner=(ControlledContraptionEntity)level.getEntity(id.get());owner.setAngle(0);if(!owner.disassemble())throw new AssertionError("Saved chassis carrier could not restore real ownership");var chassis=(ChassisBlockEntity)level.getBlockEntity(C);var cargo=((BarrelBlockEntity)level.getBlockEntity(C.east())).getItem(0);if(chassis.getRange()!=3||!chassis.getBlockState().getValue(LinearChassisBlock.STICKY_TOP)||!level.getBlockState(C.east(2)).getValue(StickerBlock.EXTENDED)||cargo.getCount()!=7||!cargo.has(DataComponents.CUSTOM_NAME))throw new AssertionError("Range/glue/latch/cargo changed during native ownership restoration");});context.waitFor(client->client.level.getBlockEntity(C) instanceof ChassisBlockEntity chassis&&chassis.getRange()==3,200);look(context,Vec3.atCenterOf(C.east()));screenshot(context,"create-vulkan-chassis-sticker-world-range-latch-and-cargo-restored");
    }
    private static void verifyMoving(ClientGameTestContext context,UUID id){context.runOnClient(client->{var owner=(ControlledContraptionEntity)find(client,id);var rendered=((ContraptionEntityRenderer)client.getEntityRenderDispatcher().getRenderer(owner)).createRenderState(owner,.5f);if(rendered.blocks.size()!=4||!rendered.actors.isEmpty())throw new AssertionError("Captured chassis/sticker invented an actor or lost ordinary models");var head=rendered.blockEntities.stream().filter(be->be.pos().equals(STICKER)).findFirst().orElseThrow();var state=(StickerRenderer.State)head.state();if(state.head.mesh==null||state.head.mesh.size()==0||state.extension!=.25f||owner.getContraption().getBlocks().get(BlockPos.ZERO).nbt().getIntOr("ScrollValue",0)!=3)throw new AssertionError("Moving native sticker/range snapshot incorrect");});}
    private static void verifySticker(ClientGameTestContext context,BlockPos pos,float extension){context.runOnClient(client->{var state=(StickerRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(pos),.5f,null,false);if(state==null||state.head.mesh==null||state.head.mesh.size()==0||Math.abs(state.extension-extension)>.001)throw new AssertionError("Native head geometry/settled source extension missing");});}
    private static void open(ClientGameTestContext context,BlockPos pos){look(context,Vec3.atCenterOf(pos));context.waitTicks(6);context.getInput().holdKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof ChassisSettingsClient.RangeScreen screen&&screen.position().equals(pos),200);}
    private static Vec2 coordinate(ClientGameTestContext context,int value){return context.computeOnClient(client->{var p=((ChassisSettingsClient.RangeScreen)client.gui.screen()).coordinate(value);float scaleX=(float)client.getWindow().getScreenWidth()/client.getWindow().getGuiScaledWidth();float scaleY=(float)client.getWindow().getScreenHeight()/client.getWindow().getGuiScaledHeight();return new Vec2(p.x*scaleX,p.y*scaleY);});}
    private static void choose(ClientGameTestContext context,int value){var p=coordinate(context,value);context.getInput().setCursorPos(p.x,p.y);context.waitTicks(3);screenshot(context,"create-vulkan-chassis-native-range-board");context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null,200);}
    private static net.minecraft.world.entity.Entity find(Minecraft client,UUID id){if(client.level==null)return null;for(var entity:client.level.entitiesForRendering())if(entity.getUUID().equals(id))return entity;return null;}
    private static void waitServer(ClientGameTestContext context,TestSingleplayerContext world,Predicate<ServerLevel> predicate,int ticks,String message){var ready=new AtomicBoolean();for(int i=0;i<ticks&&!ready.get();i++){world.getServer().runOnServer(ignored->ready.set(predicate.test(world.getConnection().getServerLevel())));if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError(message);}
    private static void look(ClientGameTestContext context,Vec3 target){var angle=context.computeOnClient(client->{var d=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-d.x,d.z)),(float)-Math.toDegrees(Math.atan2(d.y,Math.hypot(d.x,d.z))));});context.getInput().lookAt(angle.x,angle.y);}
    private static void use(ClientGameTestContext context){context.waitTicks(6);context.getInput().pressKey(options->options.keyUse);}
    private static void screenshot(ClientGameTestContext context,String name){context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot(name);}
}
